const safe=u=>({id:u.id,name:u.name,email:u.email,role:u.role,active:u.active??1,plan:u.plan||'Free',valid_until:u.valid_until||null,phone:u.phone||null,father_name:u.father_name||null,dob:u.dob||null,target_exam:u.target_exam||null,phone_verified:Number(u.phone_verified||0),last_login:u.last_login||null,login_count:Number(u.login_count||0)});
const authHits=new Map();function authRateLimit(req,res,next){const key=(req.ip||req.socket?.remoteAddress||'unknown')+':'+req.path,now=Date.now(),windowMs=15*60*1000,max=30;let x=authHits.get(key);if(!x||now-x.start>windowMs)x={start:now,count:0};x.count++;authHits.set(key,x);if(authHits.size>5000){for(const [k,v] of authHits)if(now-v.start>windowMs)authHits.delete(k)}if(x.count>max)return res.status(429).json({error:'Too many login attempts. Please try again later.'});next()}
const emailOk=v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(v||'').trim());
const normalizePhone=v=>{let d=String(v||'').replace(/\D/g,'');if(d.length===12&&d.startsWith('91'))d=d.slice(2);if(d.length===11&&d.startsWith('0'))d=d.slice(1);return /^[6-9]\d{9}$/.test(d)?'+91'+d:''};
const otpHash=(phone,purpose,code)=>crypto.createHash('sha256').update(`${phone}|${purpose}|${code}|${SECRET}`).digest('hex');
async function deliverOtp(phone,code){
 const url=String(process.env.OTP_WEBHOOK_URL||'').trim();
 if(!url){if(String(process.env.DEV_OTP_MODE||'0')==='1'){console.log(`[DEV OTP] ${phone}: ${code}`);return {dev:true}}throw Error('OTP SMS gateway is not configured on the server')}
 const headers={'Content-Type':'application/json'};if(process.env.OTP_WEBHOOK_TOKEN)headers.Authorization='Bearer '+process.env.OTP_WEBHOOK_TOKEN;
 const r=await fetch(url,{method:'POST',headers,body:JSON.stringify({mobile:phone,otp:code,message:`Your Shivjee\'s Typing OTP is ${code}. It is valid for 5 minutes.`})});
 if(!r.ok)throw Error('OTP SMS provider rejected the request');return {dev:false};
}
app.post('/api/auth/admin-register-start',authRateLimit,async(req,res)=>{try{let{name,father_name,dob,phone,email,password}=req.body||{};name=String(name||'').trim().replace(/\s+/g,' ');father_name=String(father_name||'').trim().replace(/\s+/g,' ');dob=String(dob||'').trim();phone=normalizePhone(phone);email=String(email||'').trim().toLowerCase();password=String(password||'');if(name.length<2||name.length>80)return res.status(400).json({error:'Enter a valid full name'});if(father_name.length<2||father_name.length>80)return res.status(400).json({error:"Enter father's name"});if(!/^\d{4}-\d{2}-\d{2}$/.test(dob)||new Date(dob+'T00:00:00')>new Date())return res.status(400).json({error:'Enter a valid date of birth'});if(!phone)return res.status(400).json({error:'Enter a valid 10-digit Indian mobile number'});if(!emailOk(email)||email.length>160)return res.status(400).json({error:'Enter a valid email address'});if(password.length<10||password.length>200)return res.status(400).json({error:'Admin password must be at least 10 characters'});if(db.prepare('SELECT 1 FROM users WHERE email=?').get(email))return res.status(400).json({error:'Email already registered'});if(db.prepare('SELECT 1 FROM users WHERE phone=?').get(phone))return res.status(400).json({error:'Mobile number already registered'});const latest=db.prepare("SELECT created_at FROM otp_codes WHERE phone=? AND purpose='admin_signup' ORDER BY id DESC LIMIT 1").get(phone);if(latest&&Date.now()-new Date(latest.created_at+'Z').getTime()<30000)return res.status(429).json({error:'Please wait 30 seconds before requesting another signup OTP'});const code=String(crypto.randomInt(100000,1000000)),expires=new Date(Date.now()+5*60*1000).toISOString();db.prepare("UPDATE otp_codes SET used=1 WHERE phone=? AND purpose='admin_signup' AND used=0").run(phone);db.prepare('INSERT INTO otp_codes(phone,purpose,code_hash,expires_at) VALUES(?,?,?,?)').run(phone,'admin_signup',otpHash(phone,'admin_signup',code),expires);const delivered=await deliverOtp(phone,code);const challenge=jwt.sign({type:'admin_signup',name,father_name,dob,phone,email,password_hash:bcrypt.hashSync(password,10)},SECRET,{expiresIn:'10m'});res.json({challenge,phone_masked:maskPhone(phone),...(delivered.dev?{dev_otp:code}:{})});}catch(e){res.status(503).json({error:e.message||'Could not send signup OTP'})}});
app.post('/api/auth/admin-register-verify',authRateLimit,(req,res)=>{let c;try{c=jwt.verify(String(req.body?.challenge||''),SECRET)}catch{return res.status(401).json({error:'Signup verification expired. Start again.'})}if(c?.type!=='admin_signup')return res.status(401).json({error:'Invalid signup verification'});const otp=String(req.body?.otp||'').trim();if(!/^\d{6}$/.test(otp))return res.status(400).json({error:'Enter the 6-digit OTP'});const row=db.prepare("SELECT * FROM otp_codes WHERE phone=? AND purpose='admin_signup' AND used=0 ORDER BY id DESC LIMIT 1").get(c.phone);if(!row)return res.status(400).json({error:'Request a new signup OTP'});if(new Date(row.expires_at)<new Date()){db.prepare('UPDATE otp_codes SET used=1 WHERE id=?').run(row.id);return res.status(400).json({error:'OTP expired. Start signup again.'})}if(row.attempts>=5){db.prepare('UPDATE otp_codes SET used=1 WHERE id=?').run(row.id);return res.status(429).json({error:'Too many wrong OTP attempts. Start signup again.'})}if(otpHash(c.phone,'admin_signup',otp)!==row.code_hash){db.prepare('UPDATE otp_codes SET attempts=attempts+1 WHERE id=?').run(row.id);return res.status(401).json({error:'Incorrect signup OTP'})}if(db.prepare('SELECT 1 FROM users WHERE email=? OR phone=?').get(c.email,c.phone))return res.status(400).json({error:'Email or mobile number already registered'});db.prepare('UPDATE otp_codes SET used=1 WHERE id=?').run(row.id);try{const id=db.prepare("INSERT INTO users(name,father_name,dob,target_exam,phone,email,password,role,active,plan,phone_verified) VALUES(?,?,?,?,?,?,?,?,?,?,1)").run(c.name,c.father_name,c.dob,'Administration',c.phone,c.email,c.password_hash,'admin',1,'Owner/Admin').lastInsertRowid;const u=safe(db.prepare('SELECT * FROM users WHERE id=?').get(id));res.json({created:true,user:{id:u.id,name:u.name,email:u.email,role:u.role},message:'Owner/Admin account created. Login with Email + Password + OTP.'})}catch(e){res.status(400).json({error:'Could not create Owner/Admin account'})}});
app.post('/api/auth/register',authRateLimit,(req,res)=>{if(setting('allow_registration')!=='1')return res.status(403).json({error:'New registration is currently disabled'});let{name,father_name,dob,target_exam,phone,email,password}=req.body||{};name=String(name||'').trim().replace(/\s+/g,' ');father_name=String(father_name||'').trim().replace(/\s+/g,' ');dob=String(dob||'').trim();target_exam=String(target_exam||'').trim().slice(0,120);phone=normalizePhone(phone);email=String(email||'').trim().toLowerCase();password=String(password||'');if(name.length<2||name.length>80)return res.status(400).json({error:'Enter a valid full name'});if(father_name.length<2||father_name.length>80)return res.status(400).json({error:"Enter father's name"});if(!/^\d{4}-\d{2}-\d{2}$/.test(dob)||new Date(dob+'T00:00:00')>new Date())return res.status(400).json({error:'Enter a valid date of birth'});if(!target_exam)return res.status(400).json({error:'Select the exam you are preparing for'});if(!phone)return res.status(400).json({error:'Enter a valid 10-digit Indian mobile number'});if(!emailOk(email)||email.length>160)return res.status(400).json({error:'Enter a valid email address'});if(password.length<8||password.length>200)return res.status(400).json({error:'Password must be 8–200 characters'});try{const id=db.prepare('INSERT INTO users(name,father_name,dob,target_exam,phone,email,password) VALUES(?,?,?,?,?,?,?)').run(name,father_name,dob,target_exam,phone,email,bcrypt.hashSync(password,10)).lastInsertRowid;const u=safe(db.prepare('SELECT * FROM users WHERE id=?').get(id));res.json({user:u,token:jwt.sign({id:u.id},SECRET,{expiresIn:'7d'})})}catch(e){const msg=String(e.message||'');res.status(400).json({error:msg.includes('phone')?'Mobile number already registered':'Email already registered'})}});
