 const delivered=await deliverOtp(phone,code),challenge=jwt.sign({admin2fa:u.id,type:'admin2fa'},SECRET,{expiresIn:'5m'});
 res.json({two_factor_required:true,challenge,phone_masked:maskPhone(phone),...(delivered.dev?{dev_otp:code}:{})});
