app.post('/api/admin/passages',auth,admin,(req,res)=>{const b=req.body||{},title=String(b.title||'').trim(),content=String(b.content||'').trim(),examId=Number(b.exam_id)||null;if(title.length<2||!content)return res.status(400).json({error:'Title and passage content are required'});let exam=null;if(examId){exam=db.prepare('SELECT * FROM exams WHERE id=?').get(examId);if(!exam)return res.status(400).json({error:'Selected exam not found'})}const language=exam?.language||String(b.language||'English').slice(0,40),layout=exam?.layout||String(b.layout||'QWERTY').slice(0,80);const id=db.prepare('INSERT INTO passages(title,language,layout,difficulty,content,active,highlight_mode,exam_id) VALUES(?,?,?,?,?,?,?,?)').run(title,language,layout,String(b.difficulty||'Medium').slice(0,30),content,b.active===false?0:1,['current_char','current_word','errors_only','none'].includes(b.highlight_mode)?b.highlight_mode:(exam?.highlight_mode||'current_char'),examId).lastInsertRowid;audit(req,'CREATE','passage',id,`${title}${exam?` -> ${exam.name}`:''}`);res.json({id})});
app.put('/api/admin/passages/:id',auth,admin,(req,res)=>{const b=req.body||{},id=Number(req.params.id),cur=db.prepare('SELECT * FROM passages WHERE id=?').get(id);if(!cur)return res.status(404).json({error:'Passage not found'});const title=String(b.title??cur.title).trim(),content=String(b.content??cur.content).trim();if(title.length<2||!content)return res.status(400).json({error:'Title and passage content are required'});const examId=b.exam_id===undefined?cur.exam_id:(Number(b.exam_id)||null);let exam=null;if(examId){exam=db.prepare('SELECT * FROM exams WHERE id=?').get(examId);if(!exam)return res.status(400).json({error:'Selected exam not found'})}const language=exam?.language||String(b.language??cur.language).slice(0,40),layout=exam?.layout||String(b.layout??cur.layout).slice(0,80);db.prepare('UPDATE passages SET title=?,language=?,layout=?,difficulty=?,content=?,active=?,highlight_mode=?,exam_id=? WHERE id=?').run(title,language,layout,String(b.difficulty??cur.difficulty).slice(0,30),content,b.active===undefined?cur.active:(b.active?1:0),['current_char','current_word','errors_only','none'].includes(b.highlight_mode)?b.highlight_mode:(cur.highlight_mode||'current_char'),examId,id);audit(req,'UPDATE','passage',id,title);res.json({ok:true})});
app.delete('/api/admin/passages/:id',auth,admin,(req,res)=>{const id=Number(req.params.id),cur=db.prepare('SELECT title FROM passages WHERE id=?').get(id);if(!cur)return res.status(404).json({error:'Passage not found'});db.prepare('UPDATE passages SET active=0 WHERE id=?').run(id);audit(req,'DEACTIVATE','passage',id,cur.title);res.json({ok:true})});

